  const json=value=>esc(JSON.stringify(value));
  const names={circle:'圆形',triangle:'三角形',square:'正方形',rectangle:'长方形',cube:'正方体',sphere:'球',cylinder:'圆柱',cone:'圆锥'};
  const symbols={leaf:'🌿',egg:'🥚',paw:'⭐'};
