    for(let d=0;d<=180;d+=15){const p=point(d,198),q=point(d,184),t=point(d,163);body+=`<path d="M${p}L${q}" stroke="#4b7352" stroke-width="3"/><text x="${t[0]}" y="${t[1]+5}" text-anchor="middle" font-size="16">${d}</text>`;}
